public class EntityBuilder extends BuilderBase<EntityType<?>> {
	public transient EntityBuilderFactory factory;
	public transient Consumer<MutableEntity> initialize;
	public transient EntityDimensions size;
	public transient SpawnPlacements.Type spawnPlacement;
	public transient SpawnCategory category;
	public transient int trackingRange;
	public transient int updateInterval;
	public transient boolean summonBack;
	public transient List<AttributeModifier> defaultAttributes;

	public EntityBuilder(ResourceLocation id) {
		super(id);
		this.size = EntityDimensions.scalable(1.0F, 1.0F);
		this.spawnPlacement = SpawnPlacements.Type.NO_RESTRICTIONS;
		this.category = SpawnCategory.MISC;
		this.trackingRange = 16;
		this.updateInterval = 3;
		this.summonBack = true;
		this.defaultAttributes = new ArrayList<>();
	}

	@Info("Sets the spawn placement type for this entity.")
	public EntityBuilder spawnPlacement(SpawnPlacements.Type v) {
		spawnPlacement = v;
		return this;
	}

	@Info("Sets the spawn category for this entity.")
	public EntityBuilder category(SpawnCategory v) {
		category = v;
		return this;
	}

	@Info("Sets the entity's size.")
	public EntityBuilder size(float width, float height) {
		size = EntityDimensions.scalable(width, height);
		return this;
	}

	@Info("Sets the entity's tracking range.")
	public EntityBuilder trackingRange(int v) {
		trackingRange = v;
		return this;
	}
